def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_pow_12(n):
    if n == 1:
        # n=1, n^12=1. tau(1) = 1.
        return 1

    factors = prime_factorization(n)

    # n = p1^e1 * p2^e2 * ...
    # n^12 = p1^(12*e1) * p2^(12*e2) * ...
    # tau(n^12) = (12*e1 + 1) * (12*e2 + 1) * ...

    num_divisors = 1
    for exponent in factors.values():
        num_divisors *= (12 * exponent + 1)
    return num_divisors

solutions = []
for n in range(1, 101):
    tau_val = tau_n_pow_12(n)
    if n == tau_val:
        solutions.append(n)

print(f"Solutions found for n <= 100: {solutions}")
